    if (!expr) {
        xkb_context_set_error(ctx, "Expression is null", __FILE__, __LINE__);
        return false;
    }

    switch (expr->type) {
        case EXPR_IDENTIFIER: {
            *elem_rtrn = expr->u.identifier.name;
            *field_rtrn = NULL;
            *index_rtrn = NULL;
            return true;
        }

        case EXPR_FIELD_REF: {
            const FieldRefExpr *field_expr = expr->u.field_ref;
            *elem_rtrn = field_expr->base.name;
            *field_rtrn = field_expr->field;
            *index_rtrn = NULL;
            return true;
        }

        case EXPR_ARRAY_REF: {
            const ArrayRefExpr *array_expr = expr->u.array_ref;
            *elem_rtrn = array_expr->base.name;
            *field_rtrn = NULL;
            *index_rtrn = array_expr->index;
