bool resolve_lhs(struct xkb_context *ctx, const ExprDef *expr, const char **elem_rtrn, const char **field_rtrn, ExprDef **index_rtrn) {
    if (!expr) {
        return false;
    }

    switch (expr->type) {
        case EXPR_IDENTIFIER:
            *elem_rtrn = expr->u.identifier.name;
            *field_rtrn = NULL;
            *index_rtrn = NULL;
            return true;

        case EXPR_FIELD_REF: {
            const char *field = expr->u.field_ref.field;
            const ExprDef *base_expr = expr->u.field_ref.base;

            if (!resolve_lhs(ctx, base_expr, elem_rtrn, &field_rtrn, index_rtrn)) {
                return false;
            }

            if (*field_rtrn) {
                *field_rtrn = xkb_context_build_string(ctx, "%s.%s", *field_rtrn, field);
            } else {
                *field_rtrn = strdup(field);
            }
            return true;
        }

        case EXPR_ARRAY_REF: {
            const ExprDef *index_expr = expr->u.array_ref.index;
            const ExprDef *base_expr = expr->u.array_ref.base;

            if (!resolve_lhs(ctx, base_expr, elem_rtrn, field_rtrn, index_rtrn)) {
                return false;
            }

            if (index_expr && index_expr->type == EXPR_LITERAL && index_expr->u.literal.type == LITERAL_INTEGER) {
                char *index_str = xkb_context_build_string(ctx, "%d", index_expr->u.literal.value.integer);
                *field_rtrn = xkb_context_build_string(ctx, "%s[%s]", *field_rtrn, index_str);
                free(index_str);
            } else {
                *field_rtrn = xkb_context_build_string(ctx, "%s[]", *field_rtrn);
            }

            return true;
        }

        default:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unexpected operator type when resolving LHS.");
            return false;
    }
}

bool resolve_lhs(struct xkb_context *ctx, const ExprDef *expr, const char **elem_rtrn, const char **field_rtrn, ExprDef **index_rtrn) {
    if (!expr) {
        xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Expression is NULL\n");
        return false;
    }

    switch (expr->type) {
        case EXPR_IDENTIFIER: {
            *elem_rtrn = expr->identifier;
            *field_rtrn = NULL;
            *index_rtrn = NULL;
            return true;
        }

        case EXPR_FIELD_REF: {
            if (!expr->left || expr->left->type != EXPR_IDENTIFIER) {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Invalid left-hand side of field reference\n");
                return false;
            }

            *elem_rtrn = expr->left->identifier;
            *field_rtrn = expr->field;
            *index_rtrn = NULL;
            return true;
        }

        case EXPR_ARRAY_REF: {
            if (!expr->left || expr->left->type != EXPR_IDENTIFIER) {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Invalid left-hand side of array reference\n");
                return false;
            }

            *elem_rtrn = expr->left->identifier;
            *field_rtrn = NULL;
            *index_rtrn = expr->index;
            return true;
        }

        default: {
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unexpected operator when resolving LHS\n");
            return false;
        }
    }
}
